caps2=''
for bd in ['blue','light','red']:
    b64=base64.b64encode(open(f'macspike/out2/{bd}-D1v2.png','rb').read()).decode()
    caps2+=f'<figure style="margin:0;width:400px"><img alt="Genuine capture with selected icon, badge and focus ring, {bd} backdrop" src="data:image/png;base64,{b64}" style="width:400px;border-radius:10px;box-shadow:0 0 0 1px rgba(36,31,43,.15)"><figcaption style="font:500 12px Manrope;color:#4E4757;margin-top:4px"><b>{bd} backdrop · D1 · approved label</b></figcaption></figure>'
iconopts=''.join(f'<div style="display:flex;align-items:center;gap:8px;padding:6px 10px;border-radius:8px;background:rgb(87,101,97)"><span style="width:14px;height:14px;border-radius:50%;box-shadow:inset 0 0 0 2.5px {c}"></span><span style="font:600 13px -apple-system;color:#F3ECE4">Now</span><span style="font:600 11px ui-monospace;color:#F3ECE4;margin-left:auto">{v}</span></div><div style="font:600 12px Manrope;color:#4E4757;margin:2px 0 8px">{lab}</div>' for c,v,lab in [('#5BC4B8','2.92','Approved teal: fails 3:1 over the light wallpaper'),('#A3E2D9','4.20','I1 · light teal #A3E2D9 (recommended)'),('#7FD6CB','3.60','I2 · focus teal #7FD6CB')])
mac2=('<div style="border-radius:16px;background:#FFFDF9;box-shadow:0 0 0 1px rgba(36,31,43,.1);padding:16px 18px;display:flex;flex-direction:column;gap:12px">'
 '<div style="font:800 18px Manrope">Mac D1 · second native run: selected icon, badge, focus ring (approved label) <span class="tb">I1 #A3E2D9 approved (ED-178)</span></div>'
 f'<div style="display:flex;flex-wrap:wrap;gap:16px">{caps2}<div style="width:300px">{iconopts}</div></div>'
 '<div style="font:500 13px Manrope;color:#4E4757;line-height:1.55;max-width:1300px">Measured in the captures, worst of the three backdrops (light): label #F3ECE4 on the selection pill <b>5.17:1</b> ✓; Inbox badge (teal) against the sidebar <b>4.14:1</b> ✓, digit on the badge <b>7.99:1</b> ✓; keyboard focus ring #7FD6CB against the sidebar <b>4.92:1</b> ✓; selected icon in approved teal on the pill <b>2.89:1</b> ✗ (3.62 and 3.51 on the blue and red backdrops). Choice: <b>I1</b> light teal #A3E2D9 (≥ 4.20:1, recommended, still reads as teal) or <b>I2</b> focus teal #7FD6CB (≥ 3.60:1). Verified for these three backdrops and default system settings only. Reduce Transparency, Increase Contrast, VoiceOver, keyboard order and other wallpapers: PENDING.</div></div>')
wake=blend('#D9A23A',p['surface'],0.22); wind=blend('#7A7EDE',p['surface'],0.22); trk=blend('#7A7EDE',p['ground'],0.25)
def cap(bg,ic,sym): return f'<span style="width:34px;height:34px;border-radius:50%;background:{bg};color:{ic};display:inline-flex;align-items:center;justify-content:center;font-size:17px">{sym}</span>'
def orb(shadow):
    return f'<div style="width:150px;height:150px;border-radius:50%;background:radial-gradient(closest-side,{p["raised"]} calc(100% - 13px),transparent calc(100% - 12.5px)),conic-gradient(#7A7EDE 0 85%,{trk} 85% 100%);display:flex;flex-direction:column;align-items:center;justify-content:center;{shadow}"><span style="font:800 54px/1 Manrope;color:{p["text"]}">18</span><span style="font:600 12px Manrope;color:{p["text2"]}">min left</span></div>'
def thread(dot):
    g=p['ground']; a=p['accent']; r=p['raised']; tx=p['text']
    return (f'<div style="position:relative;width:260px;height:150px;background:{g};border-radius:12px;padding:10px">'
     f'<span style="position:absolute;left:32px;top:10px;height:46px;width:4px;background:#E2725B"></span><span style="position:absolute;left:32px;top:56px;height:30px;width:4px;background:#7A7EDE"></span><span style="position:absolute;left:32px;top:86px;bottom:10px;width:0;border-left:4px dotted {dot}"></span>'
     f'<span style="position:absolute;left:21px;top:20px;width:26px;height:26px;border-radius:50%;background:#E2725B;color:{g};display:flex;align-items:center;justify-content:center;font-weight:800">&#10003;</span>'
     f'<span style="position:absolute;left:27px;top:79px;width:14px;height:14px;border-radius:50%;background:{a};border:2px solid {g};box-sizing:border-box;box-shadow:0 0 0 1px rgba(91,196,184,.45)"></span><span style="position:absolute;left:52px;top:77px;font:700 12px/18px Manrope;color:{a};padding:0 7px;border-radius:9px;background:{r};box-shadow:0 0 0 1px rgba(91,196,184,.35)">10:42</span><span style="position:absolute;left:104px;right:12px;top:86px;height:1px;background:rgba(91,196,184,.30)"></span>'
     f'<span style="position:absolute;left:21px;top:110px;width:26px;height:26px;border-radius:50%;box-shadow:inset 0 0 0 4px #D9668F"></span><span style="position:absolute;left:60px;top:114px;font:700 13px Manrope;color:{tx}">Lunch</span></div>')
knot='<svg width="40" height="34" viewBox="0 0 24 22"><path d="M12 1C3 7 21 15 12 21" fill="none" stroke="#7A7EDE" stroke-width="3.5" stroke-linecap="round"/><path d="M12 1C21 7 3 15 12 21" fill="none" stroke="#2A9D8F" stroke-width="3.5" stroke-linecap="round"/></svg>'
dots=''.join(f'<div style="text-align:center"><div style="width:70px;height:70px;background:{p["ground"]};border-radius:8px;position:relative"><span style="position:absolute;left:33px;top:6px;bottom:6px;border-left:4px dotted {d}"></span></div><div style="font:600 11px ui-monospace">{d}<br>{cr(d,p["ground"]):.2f}</div></div>' for d in ['#4A4348','#6B6369'])
det=(f'<div style="border-radius:16px;background:{p["surface"]};padding:18px;display:flex;flex-direction:column;gap:14px;color:{p["text"]};font:500 13px Manrope;width:1500px">'
 '<div style="font:800 18px Manrope">Detail tokens on P1 · derived from the approved foundation</div>'
 '<div style="display:flex;gap:30px;flex-wrap:wrap;align-items:flex-start">'
 f'<div style="width:300px"><b>Wake Up / Wind Down caps</b><div style="display:flex;gap:16px;margin:8px 0">{cap(wake,"#D9A23A","&#9728;")}{cap(wind,"#A9ACEB","&#9790;")}</div>Wake: amber at 22 % over surface ({wake}), icon amber #D9A23A <b>{cr("#D9A23A",wake):.2f}</b>. Wind Down: indigo at 22 % ({wind}), icon #A9ACEB <b>{cr("#A9ACEB",wind):.2f}</b> (lighter indigo; light mode uses a deeper one). Same 32 / 34 px shapes; the time beside them is secondary text. <span class="tb">Derived</span></div>'
 f'<div style="width:420px"><b>Large now-dot</b><div style="display:flex;gap:16px;margin:8px 0">{orb("")}{orb("box-shadow:0 18px 40px rgba(0,0,0,.45)")}</div>Centre raised #28232A; numeral #F3ECE4 <b>{cr(p["text"],p["raised"]):.1f}</b>; "min left" #C7BEC4 <b>{cr(p["text2"],p["raised"]):.1f}</b>; arc in the task\'s dark colour (indigo {cr("#7A7EDE",p["ground"]):.2f} on ground, {cr("#7A7EDE",trk):.2f} on its track); track the colour at 25 % ({trk}), decorative as in light (1.18). <span class="tb">T1 approved: no shadow (left) (ED-178)</span></div>'
 f'<div style="width:300px"><b>Thread, knot and now-bead</b><div style="display:flex;gap:12px;margin:8px 0">{thread("#6B6369")}</div>Solid segments: the task\'s dark colour. Overlap knot {knot} in the two task colours, label secondary. Now-bead #5BC4B8 ({cr(p["accent"],p["ground"]):.2f} on ground) with a 2 px ground border and a 45 % teal ring; time pill teal on raised <b>{cr(p["accent"],p["raised"]):.2f}</b> with a 35 % teal edge; now line teal 30 % (decorative). <span class="tb">Derived</span></div>'
 f'<div style="width:330px"><b>Dotted "ahead" thread</b><div style="display:flex;gap:12px;margin:8px 0">{dots}</div>Light mode\'s dotted line is decorative (#BEB6C7, 1.84:1). <b>T2-A</b> #4A4348 matches that strength (1.91). <b>T2-B</b> #6B6369 (3.15, recommended): the dotted pattern marks "ahead" time, so it meets 3:1 in dark. <span class="tb">T2-B #6B6369 approved (ED-178)</span> on the ground (3.15:1). <span class="tb">Q1-B (ED-179)</span> #7B7279 only on surface, raised, sheet and tinted rows where measured (3.03–3.67:1); dimmed behind scrims; popover 2.72:1 would need its own correction.</div>'
 '</div>'
 f'<div style="font-size:12px;color:{p["text2"]}">No new glows, halos or task-state meanings. Ahead = coloured ring; now = arc and bead; done = filled dot with a check. Decorative: the now track and the now line. Text corrections (ED-179): placeholder #6F6978 light / #A0999F dark; hex prefix in secondary text.</div></div>')
